def backfill_product_availability_and_pricing(apps, schema_editor):
    Product = apps.get_model('products', 'Product')
    # 1. Backfill availability_mode based on legacy is_available
    Product.objects.filter(is_available=False).update(availability_mode='OUT_OF_STOCK')
    Product.objects.filter(is_available=True).update(availability_mode='IN_STOCK')

    # 2. Backfill price_display_mode
    # Published products with null price become CONTACT_FOR_PRICE
    Product.objects.filter(price__isnull=True, status='PUBLISHED').update(price_display_mode='CONTACT_FOR_PRICE')
    # Products with a price set become SHOW_PRICE
    Product.objects.filter(price__isnull=False).update(price_display_mode='SHOW_PRICE')
    # Drafts with null price become SHOW_PRICE
    Product.objects.filter(price__isnull=True, status='DRAFT').update(price_display_mode='SHOW_PRICE')


def reverse_backfill(apps, schema_editor):
    Product = apps.get_model('products', 'Product')
    Product.objects.filter(availability_mode='OUT_OF_STOCK').update(is_available=False)
    Product.objects.filter(availability_mode__in=['IN_STOCK', 'MADE_TO_ORDER']).update(is_available=True)


